select
from t_agent_workflow where project_id = #{projectId,jdbcType=VARCHAR} and deleted = false
and id = #{workflowSearchCriteria.id,jdbcType=VARCHAR}
and workspace_id = #{workflowSearchCriteria.workspaceId,jdbcType=VARCHAR}
and name like concat('%', #{workflowSearchCriteria.name,jdbcType=VARCHAR}, '%') escape '!'
and description like concat('%', #{workflowSearchCriteria.description,jdbcType=VARCHAR}, '%') escape '!'
and created_by like concat('%', #{workflowSearchCriteria.creator,jdbcType=VARCHAR}, '%') escape '!'
and workflow_type = #{workflowSearchCriteria.type,jdbcType=VARCHAR}
and code like concat('%', #{workflowSearchCriteria.code,jdbcType=VARCHAR}, '%') escape '!'
and customize_node = 1
and (customize_node is null or customize_node!=1)
and status = #{workflowSearchCriteria.status,jdbcType=VARCHAR}
order by updated_at desc

select w.*,r.version_id,r.version_name from ( select
from t_agent_workflow where project_id = #{projectId,jdbcType=VARCHAR} and deleted = false
and id in
#{workflow_id}
and name like concat('%', #{workflowSearchCriteria.name,jdbcType=VARCHAR}, '%') escape '!'
and description like concat('%', #{workflowSearchCriteria.description,jdbcType=VARCHAR}, '%') escape '!'
and created_by like concat('%', #{workflowSearchCriteria.creator,jdbcType=VARCHAR}, '%') escape '!'
and workflow_type = #{workflowSearchCriteria.type,jdbcType=VARCHAR}
and workspace_id = #{workflowSearchCriteria.workspaceId,jdbcType=VARCHAR}
and last_version_id is not null ) as w inner join t_release_version as r on w.id=r.app_id and w.last_version_id=r.version_id and r.app_type='workflow' order by COALESCE(w.published_at, w.updated_at) desc

